python3 -c "
import zipfile, re
from xml.etree import ElementTree as ET

M = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
z = zipfile.ZipFile('budget.xlsx')
root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

def col_letter(ref):
    return re.match(r'[A-Z]+', ref).group()

rows = []
for row in root.iter('{%s}row' % M):
    cells = {}
    for c in row:
        ref = c.get('r')
        v = c.find('{%s}v' % M)
        val = v.text if v is not None else None
        isel = c.find('{%s}is' % M)
        if isel is not None:
            val = ''.join(x.text or '' for x in isel.iter('{%s}t' % M))
        cells[col_letter(ref)] = val
    rows.append(cells)

# Print as grid
all_cols = []
for cells in rows:
    for k in cells:
        if k not in all_cols:
            all_cols.append(k)
all_cols.sort(key=lambda x: (len(x), x))
for i, cells in enumerate(rows, start=1):
    print('Row', i, {k: cells.get(k) for k in all_cols})
"

